namespace SrpLab;
public sealed class StockAllocator { public IReadOnlyList<(string Sku,int Allocated)> Allocate(IEnumerable<(string Sku,string Aisle,int Bin,int Need,int OnHand)> lines){var result=new List<(string,int)>();foreach(var line in lines)result.Add((line.Sku,Math.Min(line.Need,line.OnHand)));return result;} }
public sealed class WarehouseWalkingRoutePlanner { public IReadOnlyList<(string Aisle,int Bin,string Sku,int Qty)> Plan(IEnumerable<(string Sku,string Aisle,int Bin,int Need,int OnHand)> lines){return lines.OrderBy(x=>x.Aisle).ThenBy(x=>x.Bin).Select(x=>(x.Aisle,x.Bin,x.Sku,Math.Min(x.Need,x.OnHand))).Where(x=>x.Item4>0).ToList();} }
public sealed class PickerScriptComposer { public string Compose(IReadOnlyList<(string Aisle,int Bin,string Sku,int Qty)> route,IReadOnlyList<(string Sku,int Allocated)> allocations,IEnumerable<(string Sku,string Aisle,int Bin,int Need,int OnHand)> lines){var steps=route.Select((s,i)=>$"{i+1}. Go aisle {s.Aisle} bin {s.Bin}: pick {s.Qty} × {s.Sku}");var shortages=allocations.Where(a=>a.Allocated<lines.First(x=>x.Sku==a.Sku).Need).Select(x=>x.Sku);return string.Join('\n',steps)+"\n"+(shortages.Any()?"SHORTAGES: "+string.Join(", ",shortages):"SHORTAGES: none");} }
public sealed class WmsBatchXmlFormatter { public string Format(string id,IReadOnlyList<(string Sku,int Allocated)> allocations){return $"<batch id=\"{id}\">{string.Join("",allocations.Select(x=>$"<line sku=\"{x.Sku}\" qty=\"{x.Allocated}\" />"))}</batch>";} }
